    def countPairs(self, root: Optional[TreeNode], distance: int) -> int:
        self.result = 0

        def dfs(node):
            # returns list of leaf distances
            if not node:
                return []
            if not node.left and not node.right:
                return [1]  # leaf distance from itself
            left_distances = dfs(node.left)
            right_distances = dfs(node.right)
            # count pairs
            for ld in left_distances:
                for rd in right_distances:
                    if ld + rd <= distance:
                        self.result += 1
            # collect distances for parent's use
            new_distances = [d + 1 for d in left_distances + right_distances if d + 1 < distance]
            return new_distances
